// ===== Бодит мэдээнүүд (2026-11-19) — өдөр бүр шинэчлэгдэнэ =====
const ARTICLES = [
  {id:1, cat:"uls-tor", title:"ТББХ Ерөнхийлөгчийн чөлөөлөгдөх хүсэлтийг дэмжлээ — УИХ өнөөдөр шийдвэрлэнэ", titleEn:"Standing Committee backs President's request to step down; Parliament to decide today", time:"15 мин", timeEn:"15 min", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Mongolian%20Government%20Palace%20and%20Tamgha%20statue.jpg?width=1000", text:"Улсын Их Хурлын Төрийн байгуулалтын байнгын хороо өчигдөр буюу арваннэгдүгээр сарын 18-нд хуралдаж, Монгол Улсын Ерөнхийлөгч У.Хүрэлсүхийн үүрэгт ажлаасаа чөлөөлөгдөх хүсэлтийг дэмжлээ. Хуралдаан 13:46 цагт 56.3 хувийн ирцтэйгээр эхэлж, оролцсон гишүүдийн 77.8 хувь нь хүсэлтийг дэмжсэн байна. Байнгын хорооны дарга Б.Жавхлан хүсэлтийг танилцуулсан бөгөөд гишүүдээс асуулт асууж, санал хэлсэн хүн гараагүй гэж мэдээллээ.\n\nЕрөнхийлөгч У.Хүрэлсүх чөлөөлөгдөх хүсэлтээ арваннэгдүгээр сарын 17-ны өдөр УИХ-ын дарга С.Бямбацогтод албан бичгээр хүргүүлсэн юм. Тэрбээр хоёр хоногийн өмнө хэвлэлийнхэнд мэдэгдэл хийхдээ өөрт нь тулгараад буй авлигын хэргийн талаарх гүтгэлэг худал болохыг нотлохын тулд албан тушаалаа өгч, жирийн иргэний хувиар шалгуулна гэж мэдэгдсэн байна.\n\nЭнэ хэрэг нь 2019 онд түүнийг Ерөнхий сайдаар ажиллаж байх үед Тавантолгой-Гашуунсухайт чиглэлийн 234 км төмөр зам барих гэрээг тендер зарлалгүйгээр «Боди Интернэшнл» компанид олгосонтой холбоотой юм. Улаанбаатар хотын дарга асан Х.Нямбаатар арваннэгдүгээр сарын 14-нд төмөр замын урьдчилгаа төлбөрөөс 110 сая ам.доллар улс төрчдөд хахууль болон очсон, үүний 25 сая ам.долларыг нь Хүрэлсүх авсан гэж мэдэгдсэн байна. Ерөнхийлөгч үүнийг эрс няцааж, ард түмнээсээ, төрөөсөө хэзээ ч хулгайлж байгаагүй гэж мэдэгджээ.\n\nАсуудлыг өнөөдөр буюу арваннэгдүгээр сарын 19-нд УИХ-ын чуулганы нэгдсэн хуралдаанаар хэлэлцэж, санал хураалт явуулна. Хүсэлтийг олонх дэмжвэл Ерөнхийлөгчийг үүрэгт ажлаас нь чөлөөлөх тухай хууль баталсанд тооцогдох бөгөөд УИХ-ын дарга Ерөнхийлөгчийн бүрэн эрхийг түр хэрэгжүүлж, дөрвөн сарын дотор Ерөнхийлөгчийн ээлжит бус сонгууль зарлан явуулна.\n\nХүсэлт хүлээн авагдвал энэ нь Монголын түүхэнд төрийн тэргүүн өөрийн хүсэлтээр албан тушаалаа өгч буй анхны тохиолдол болох юм. Хүрэлсүх 2021 онд Ерөнхийлөгчөөр сонгогдсон бөгөөд өмнө нь өндөр албан тушаалаас өөрийн хүсэлтээр дөрөв дэх удаагаа чөлөөлөгдөж байна.", textEn:"The State Great Khural's Standing Committee on State Structure met yesterday, November 18, and backed President U. Khurelsukh's request to be relieved of his duties. The session began at 13:46 with 56.3 percent attendance, and 77.8 percent of the members present supported the request. Committee chair B. Javkhlan presented the request, and no member asked questions or spoke on it, according to reports.\n\nPresident Khurelsukh submitted his request in writing to Parliament Speaker S. Byambatsogt on November 17. Two days earlier, speaking to journalists, he said he would step down and submit to investigation as an ordinary citizen in order to prove that the corruption allegations against him are false.\n\nThe case concerns a contract awarded in 2019, when he was prime minister, to build the 234-kilometre Tavantolgoi-Gashuunsukhait railway without a tender, to the company Bodi International. Former Ulaanbaatar mayor Kh. Nyambaatar said on November 14 that 110 million US dollars from the railway's advance payment had gone to politicians as kickbacks, including 25 million dollars to Khurelsukh. The President strongly denied this, saying he had never stolen from his people or his state.\n\nParliament's plenary session will discuss the matter today, November 19, and hold a vote. If a majority supports the request, the law relieving the President of his duties will be considered adopted, the Speaker will exercise presidential powers on an interim basis, and an extraordinary presidential election must be called within four months.\n\nIf the request is accepted, it will be the first time in Mongolia's history that a head of state has voluntarily stepped down. Khurelsukh was elected President in 2021 and is now leaving a senior post at his own request for the fourth time."},
  {id:2, cat:"uls-tor", title:"Ерөнхий сайд Н.Учрал: Гашуунсухайтын төмөр замын асуудал Х.Баттулгаас эхтэй", titleEn:"PM Uchral: Gashuunsukhait railway issue began under Kh. Battulga", time:"30 мин", timeEn:"30 min", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Trans-Mongolian%20Railway%20%2849310230272%29.jpg?width=760", text:"Ерөнхий сайд Н.Учрал өчигдөр буюу арваннэгдүгээр сарын 18-нд мэдэгдэл хийж, Гашуунсухайтын төмөр замтай холбоотой асуудал өмнөх Ерөнхийлөгч Х.Баттулгын үеэс эхтэй гэж мэдэгдлээ. Тэрбээр асуудлыг шалгах хугацаатай үүргийг хууль хяналтын байгууллагад өгөхөө зарласан байна.\n\nЕрөнхий сайдын мэдэгдснээр Гашуунсухайтын төмөр зам, «Бодь» группийн оффтейк гэрээтэй нэр холбогдсон, тухайн үед Үндэсний аюулгүй байдлын зөвлөлийн гишүүнээр ажиллаж байсан бүх өндөр албан тушаалтан нам харгалзахгүй шалгуулах ёстой аж. Тэрбээр УИХ-ын гишүүний халдашгүй эрхэд нуугдах эрх хэнд ч байхгүй гэж онцолсон байна.\n\nЭнэ асуудал нь Ерөнхийлөгч У.Хүрэлсүхийн чөлөөлөгдөх хүсэлтийн гол үндэс болсон Тавантолгойн төмөр замын урьдчилгаа төлбөртэй холбоотой 110 сая ам.долларын авлигын хэргийн хүрээнд өрнөж байна. Улаанбаатар хотын дарга асан Х.Нямбаатар арваннэгдүгээр сарын 14-нд уг мөнгийг улс төрчдөд хахууль болон очсон гэж мэдэгдсэн бөгөөд «Бодь Интернэшнл» компани болон нэр холбогдсон албан тушаалтнууд үүнийг няцааж байгаа юм.\n\nМэдэгдлийнхээ үеэр Ерөнхий сайд шатахууны хангамжийн талаар ч тайлбар хийлээ. Тэрбээр Монгол Улс шатахууны 97 орчим хувийг ОХУ-аас авдаг байсан бол одоо 70 хувийг ОХУ-аас, 30 хувийг БНХАУ, БНСУ зэрэг орноос нийлүүлж байгаа, Хөгжлийн банкаар дамжуулан нөөц бүрдүүлсэн гэж мэдэгдсэн байна. Хууль хяналтын байгууллагын шалгалтын дүн ойрын хугацаанд гарах төлөвтэй байна.", textEn:"Prime Minister N. Uchral said yesterday, November 18, that the issues surrounding the Gashuunsukhait railway began under former President Kh. Battulga. He announced that he had given law-enforcement agencies a deadline-bound instruction to investigate the matter.\n\nAccording to the Prime Minister, every senior official who was a member of the National Security Council at the time and is named in connection with the Gashuunsukhait railway and the Bodi Group's offtake contract must be investigated regardless of party. He stressed that no one has the right to hide behind a member of parliament's immunity.\n\nThe matter is unfolding within the alleged 110-million-US-dollar corruption case linked to the advance payment for the Tavantolgoi railway, which is the main basis for President U. Khurelsukh's request to step down. Former Ulaanbaatar mayor Kh. Nyambaatar said on November 14 that the money had gone to politicians as kickbacks, a claim denied by Bodi International and the officials named.\n\nIn the same statement, the Prime Minister also addressed fuel supplies. He said Mongolia used to import about 97 percent of its fuel from Russia, but now takes 70 percent from Russia and 30 percent from countries including China and South Korea, and has built up reserves through the Development Bank. The findings of the law-enforcement investigation are expected soon."},
  {id:3, cat:"ediin-zasag", title:"Шатахууны үнэ буурлаа: энгийн АИ-92 150, «Евро» АИ-92 1000 төгрөгөөр хямдарна", titleEn:"Fuel prices fall: regular AI-92 down 150 tugriks, Euro AI-92 down 1,000", time:"45 мин", timeEn:"45 min", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Bishkek%2003-2016%20img21%20Akhunbaev%20Street%20petrol%20station.jpg?width=760", text:"Засгийн газрын өчигдөр буюу арваннэгдүгээр сарын 18-нд болсон ээлжит хуралдаанаар шатахууны үнийг бууруулах шийдвэр гаргалаа. Арваннэгдүгээр сарын 18-наас 19-нд шилжих шөнөөс эхлэн энгийн АИ-92 автобензиний литрийн үнэ 150 төгрөгөөр, «Евро-3» болон түүнээс дээш стандартын АИ-92-ынх 1000 хүртэл төгрөгөөр буурна.\n\n«Евро-3» болон түүнээс дээш стандартын АИ-92 автобензиний жижиглэнгийн үнийг хилийн үнэтэй уялдуулан литр тутамд 1000 хүртэл төгрөгөөр бууруулах зохицуулалтыг шатахууны жижиглэн худалдаа эрхлэгч аж ахуйн нэгжүүдтэй хамтран хэрэгжүүлэхээр Засгийн газрын тогтоол баталсан байна. Газрын тосны бүтээгдэхүүний шаардлагатай нөөц бүрдүүлэх, хангамжийг тогтворжуулах нь тогтоолын зорилго юм.\n\nУлаанбаатар хотын хэмжээнд 270 шатахуун түгээх станц үйл ажиллагаа явуулдаг бөгөөд эдгээрээс 204 нь хэвийн ажиллаж байна. Бусад станцад зарим төрлийн шатахуун хангалтгүй, дууссан байгаа аж. Гэсэн хэдий ч хотод үүсээд байсан шатахууны хомсдол, дарааллын асуудал одоогоор хэвийн хэмжээнд очсон гэж Шатахууны шуурхай штабаас мэдээллээ.\n\nОХУ-аас шатахууны нийлүүлэлт, захиалгын тоог нэмэгдүүлсэнтэй холбоотойгоор арваннэгдүгээр сард захиалга хэвийн үргэлжилж байна. Салбарын мэдээллээр АИ-92 бензиний үнэ өмнө нь 2590 төгрөгөөс 3600 төгрөг болж, 39 орчим хувиар өссөн бол импортын худалдан авах үнэ тонн тутамд 705 ам.доллараас 1070 ам.долларт хүрсэн байна. Сард 75-85 мянган тонн бензин хэрэглэдэг зах зээлд гэрээгээр тохирсон нийлүүлэлтийн доод хэмжээ 50 мянган тонн орчим байгаа нь хомсдолын гол шалтгаан болсон гэж салбарын эх сурвалж тайлбарлаж байна.", textEn:"The Cabinet decided at its regular meeting yesterday, November 18, to cut fuel prices. From the night of November 18-19, the price of regular AI-92 petrol falls by 150 tugriks a litre, and Euro-3 and higher standard AI-92 by up to 1,000 tugriks a litre.\n\nThe Government approved a resolution to cut the retail price of Euro-3 and higher AI-92 by up to 1,000 tugriks a litre, aligning it with the border price, in cooperation with fuel retailers. The aim is to build up the required reserves of petroleum products and stabilise supplies.\n\nOf the 270 petrol stations operating in Ulaanbaatar, 204 are working normally. Some fuel types are in short supply or out of stock at the others, but the fuel shortage and queues that had built up in the capital have now returned to normal levels, the fuel emergency headquarters said.\n\nOrders from Russia increased in November, and deliveries are proceeding normally this month. According to industry sources, the price of AI-92 petrol had earlier risen from 2,590 to 3,600 tugriks, about 39 percent, while the import purchase price rose from 705 to 1,070 US dollars a tonne. The market consumes 75,000-85,000 tonnes of petrol a month, while the contracted minimum supply is about 50,000 tonnes, which industry sources describe as the main cause of the shortage."},
  {id:4, cat:"ediin-zasag", title:"Оюу Толгойн 3 их наяд төгрөгийг иргэн бүрд 857 мянгаар олгох өргөдлийг Байнгын хороод хэлэлцлээ", titleEn:"Committees take up petition to pay Oyu Tolgoi's 3 trillion tugriks at 857,000 per citizen", time:"1 цаг", timeEn:"1 hour", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Oyu%20Tolgoi%2007.JPG?width=760", text:"Улсын Их Хурлын Өргөдлийн болон Эдийн засгийн байнгын хороо өчигдөр буюу арваннэгдүгээр сарын 17-нд хамтран хуралдаж, Оюу Толгойн ашгаас иргэн бүрд 857,000 төгрөгийг хувь дансанд нь шилжүүлж өгөх асуудлаар хуулийн төсөл санаачлах тухай нийтийн өргөдлийг хэлэлцлээ. Хуралдаан Төрийн ордны «Их Эзэн Чингис хаан» танхимд 64 хувийн ирцтэйгээр 15:00 цагт эхэлсэн байна.\n\nИргэн Хоролдоржийн Оюунбилэгээс ирүүлсэн өргөдлийг 2026 оны аравдугаар сарын 14-нд гаргаж, мөн сарын 23-нд Нийтийн өргөдлийн системд нийтэлжээ. Өргөдөлд «Оюу толгойн ордоо 30 жил ашиглуулсны эцэст анх удаа Монгол Улс 3 их наядын ашиг авахаар болсон. Нийт 3.5 сая иргэндээ хуваавал нэг иргэнд 857,000 төгрөг оногдож байна. Иймд иргэн бүрийн хувь дансанд бэлнээр шилжүүлэх хуулийн төслийг санаачилж байна» гэж дурдсан байна. Уг өргөдлийг 10 хоногийн дотор 100,094 иргэн дэмжсэн бөгөөд тэдний олонх буюу 71,931 нь эмэгтэйчүүд ажээ.\n\nХэлэлцүүлгийн үеэр Сангийн сайд З.Мэндсайхан Оюу Толгойн ногдол ашиг олгох хугацааг 2027 онд болгож наашлуулсан, ирэх онд 3 их наяд төгрөгийн ногдол ашиг олгохоор «Оюу Толгой» компани, «Рио Тинто» группээс Засгийн газарт захидал ирүүлснийг танилцууллаа. Тэрбээр Засгийн газар 2027 онд 3 их наяд төгрөгийг төвлөрүүлэхээр төлөвлөгөө гарган ажиллаж байгаа гэж мэдэгдсэн байна.\n\nӨргөдлийг арваннэгдүгээр сарын 5-ны өдрийн чуулганы нэгдсэн хуралдаанд танилцуулсан бөгөөд УИХ-ын гишүүн Ч.Лодойсамбуу нийтийн өргөдлийн системд босго давж, дэмжлэг авсан өргөдлүүдийг ирүүлсэн дарааллаар хэлэлцэх ёстой гэсэн байр суурь илэрхийлсэн байна. Харин УИХ-ын гишүүн С.Эрдэнэбат ногдол ашгийг ахмад настан, хөгжлийн бэрхшээлтэй иргэд, цалинтай ээжүүдэд бэлнээр өгөх, эсвэл сургалтын төлбөр, зээл төлөх зэргээр уян хатан зохицуулах боломжтой эсэхийг тодруулсан байна. Ногдол ашгийг шууд олгох эсэх маргаан үргэлжилж байгаа бөгөөд Ерөнхийлөгч шууд олгох чиглэл өгсөн бол Засгийн газар одоогийн Үндэсний баялгийн сангийн хуулийг баримтална гэж мэдэгдсэн юм.", textEn:"The State Great Khural's Standing Committees on Petitions and on Economy met jointly yesterday, November 17, to discuss a public petition calling for a bill to transfer 857,000 tugriks to each citizen's personal account from Oyu Tolgoi's profits. The meeting began at 15:00 in the Chinggis Khaan Hall of the State Palace with 64 percent attendance.\n\nThe petition, submitted by citizen Khoroldorj Oyunbileg on October 14, 2026, was published in the public petitions system on October 23. It says: «After 30 years of operating the Oyu Tolgoi deposit, Mongolia is set to receive 3 trillion tugriks in profit for the first time. Divided among our 3.5 million citizens, that is 857,000 tugriks per person. We therefore propose a bill to transfer it in cash to each citizen's personal account.» Within 10 days, 100,094 citizens supported the petition, most of them — 71,931 — women.\n\nDuring the discussion, Finance Minister Z. Mendsaikhan said the date for paying the Oyu Tolgoi dividend had been brought forward to 2027, and read out a letter from Oyu Tolgoi LLC and the Rio Tinto Group confirming plans to pay 3 trillion tugriks in dividends next year. He said the Government is working on a plan to collect the 3 trillion tugriks in 2027.\n\nThe petition was presented at the plenary session on November 5. MP Ch. Lodoytsambuu said petitions that pass the threshold in the public petitions system should be discussed in the order they were submitted. MP S. Erdenebat asked whether the dividend could be paid flexibly — in cash to older people, people with disabilities and mothers on salary, or used for tuition and loan payments. The debate over paying the dividend directly to citizens continues: the President has directed the Government to pay it directly, while the Cabinet says it will keep to the current National Wealth Fund law."},
  {id:5, cat:"niigem", title:"Өнөөдөр, маргааш Сэлэнгэ, Хэнтий, Дорнод, Сүхбаатарын нутгаар цас орж, шуурна", titleEn:"Snow and blizzards expected in Selenge, Khentii, Dornod and Sukhbaatar today and tomorrow", time:"1 цаг", timeEn:"1 hour", img:"https://commons.wikimedia.org/wiki/Special:FilePath/1600%20block%20of%2021st%20Street%2C%20N.W.%20-%20Blizzard%20of%202010.JPG?width=760", text:"Цаг уур, орчны шинжилгээний газраас цаг агаарын аюултай үзэгдлээс сэрэмжлүүлж байна. Өнөөдөр буюу арваннэгдүгээр сарын 19-нд Сэлэнгэ, Хэнтийн хойд, Төв аймгийн зүүн хойд, Дорнодын зарим сумдын нутгаар 0.0-2.0 миллиметр цас орж, цасан шуурга шуурна. Маргааш буюу арваннэгдүгээр сарын 20-нд Сэлэнгийн зүүн, Хэнтий, Дорнод, Сүхбаатарын зарим сумдын нутгаар мөн цас орж, шуурга шуурах төлөвтэй байна.\n\nСалхи өнөөдөр говь, тал, хээрийн нутгаар, маргааш нутгийн зүүн хэсгээр секундэд 14-16 метр хүрч ширүүсч, зам, даваа, гүвээнд үзэгдэх орчин хязгаарлагдаж, халтиргаа гулгаа, мөстөлт үүсэхийг малчид, иргэд, тээвэрчдэд анхааруулж байна. Өчигдөр буюу арваннэгдүгээр сарын 18-нд Хөвсгөл, Дорнодын зарим, Сэлэнгийн зүүн, Хэнтийн хойд, Төв аймгийн зүүн хойд сумдын нутгаар 0.0-1.0 миллиметр цас орж, зөөлөн цасан шуурга шуурсан юм.\n\nШөнөдөө Дархадын хотгор, Завхан, Заг-Байдраг голын эх, Хүрэнбэлчир орчим, Идэр, Тэс голын хөндийгөөр 16-21 хэм, Хангай, Хөвсгөл, Хэнтийн уулархаг нутаг, голын хөндийгөөр 10-15 хэм, Их нууруудын хотгор, говийн бүс нутгийн баруун өмнөд хэсгээр 0-5 хэм, бусад нутгаар 5-10 хэм хүйтэн байна. Өдөртөө уулархаг нутгаар 15-20 хэм, говийн бүс нутгийн өмнөд хэсгээр 1 хэм хүйтнээс 6 хэм дулаан, бусад нутгаар 7-12 хэм хүйтэн байх төлөвтэй байна.\n\nУлаанбаатар хот орчмоор өнөөдөр үүлшинэ, ялимгүй цас орно. Салхи баруун хойноос секундэд 5-10 метр, шөнөдөө 14-16 хэм, өдөртөө 6-8 хэм хүйтэн байна. Иргэд хол замд гарахдаа бэлтгэлтэй байж, цаг агаарын мэдээг тогтмол авахыг цаг уурын байгууллагаас зөвлөж байна.", textEn:"The National Agency for Meteorology and Environmental Monitoring has warned of dangerous weather. Today, November 19, snow of 0.0-2.0 millimetres and blizzards are expected in Selenge, northern Khentii, north-eastern Tuv and some soums of Dornod. Tomorrow, November 20, snow and blizzards are also expected in eastern Selenge and some soums of Khentii, Dornod and Sukhbaatar.\n\nWinds will strengthen to 14-16 metres per second across the Gobi, steppe and field regions today and in the eastern part of the country tomorrow, and herders, residents and drivers are warned that visibility will be limited on roads, passes and hills, with slippery conditions and icing. Yesterday, November 18, snow of 0.0-1.0 millimetres fell in Khuvsgul, parts of Dornod, eastern Selenge, northern Khentii and north-eastern Tuv, with light blizzards.\n\nOvernight temperatures will fall to minus 16-21 degrees in the Darkhad depression, the headwaters of the Zavkhan, Zag and Baidrag rivers, around Khurenbelchir and the Ider and Tes river valleys, minus 10-15 in the Khangai, Khuvsgul and Khentii mountains and river valleys, 0 to minus 5 in the Great Lakes depression and the south-western Gobi, and minus 5-10 elsewhere. During the day it will be minus 15-20 in the mountains, minus 1 to plus 6 in the southern Gobi, and minus 7-12 elsewhere.\n\nAround Ulaanbaatar today it will be mostly cloudy with slight snow. Winds from the north-west at 5-10 metres per second; minus 14-16 degrees overnight and minus 6-8 during the day. The weather agency advises residents to prepare carefully before long journeys and to follow weather updates regularly."},
  {id:6, cat:"oron-nutag", title:"СЭЛЭНГЭ: Цас орж, үзэгдэх орчин хязгаарлагдахыг анхаарууллаа", titleEn:"SELENGE: Snow to limit visibility, drivers warned", time:"2 цаг", timeEn:"2 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/19th%20Street%2C%20N.W.%20in%20Dupont%20Circle%20-%20Blizzard%20of%202010.JPG?width=760", text:"Сэлэнгэ аймгийн нутгаар өнөөдөр буюу арваннэгдүгээр сарын 19-нд цас орж, цасан шуурга шуурч, үзэгдэх орчин хязгаарлагдахыг Цаг уур, орчны шинжилгээний газраас анхаарууллаа. Аймагт 0.0-2.0 миллиметр цас орох төлөвтэй байгаа бөгөөд салхи секундэд 14-16 метр хүрч ширүүснэ.\n\nЦас, шуурганы улмаас зам, даваа, гүвээнд үзэгдэх орчин хязгаарлагдаж, халтиргаа гулгаа, мөстөлт үүсэх эрсдэлтэй байна. Малчид, иргэд, тээвэрчдэд хол замд гарахдаа онцгой анхаарал болгоомжтой байхыг анхааруулж байна. Маргааш буюу арваннэгдүгээр сарын 20-нд Сэлэнгийн зүүн сумдын нутгаар мөн цас орж, шуурга шуурах төлөвтэй байна.\n\nСэлэнгэ нь Монгол орны хойд хэсгийн хөдөө аж ахуй, тээврийн чухал бүс бөгөөд Улаанбаатар хотыг ОХУ-тай холбосон гол зам тус аймгаар дайран өнгөрдөг. Цаг агаарын хүндрэл нь зам тээврийн хөдөлгөөнд шууд нөлөөлдөг тул жолооч нар хурдаа тохируулж, замын нөхцөл байдлыг урьдчилан шалгахыг зөвлөж байна.\n\nЦаг уурын байгууллагын мэдээлснээр өчигдөр Сэлэнгийн зүүн сумдын нутгаар 0.0-1.0 миллиметр цас орж, зөөлөн цасан шуурга шуурсан байна. Иргэд цаг агаарын мэдээг тогтмол авч, шаардлагатай үед хол замд гарахаас татгалзахыг анхааруулж байна.", textEn:"The National Agency for Meteorology and Environmental Monitoring has warned that snow and blizzards in Selenge aimag today, November 19, will limit visibility. Snow of 0.0-2.0 millimetres is expected in the aimag, with winds strengthening to 14-16 metres per second.\n\nSnow and blizzards may limit visibility on roads, passes and hills, with slippery conditions and icing. Herders, residents and drivers are urged to take particular care before long journeys. Tomorrow, November 20, snow and blizzards are also expected in the eastern soums of Selenge.\n\nSelenge is a key agricultural and transport region in northern Mongolia, and the main road linking Ulaanbaatar with Russia passes through the aimag. Because bad weather directly affects road traffic, drivers are advised to adjust their speed and check road conditions in advance.\n\nAccording to the weather agency, snow of 0.0-1.0 millimetres fell in the eastern soums of Selenge yesterday, with light blizzards. Residents are advised to follow weather updates regularly and to avoid long journeys when necessary.", region:"selenge"},
  {id:7, cat:"ediin-zasag", title:"Ургац хураалт: энэ жил 1.4 сая тонн ургац хураан авлаа", titleEn:"Harvest: 1.4 million tonnes gathered this year", time:"2 цаг", timeEn:"2 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Combine%20in%20wheat%20field.jpg?width=760", text:"2026 оны ургац хураалтын урьдчилсан дүнгээр улсын хэмжээнд нийт 1.4 сая тонн ургац хураан авсан тухай Засгийн газрын өчигдөр буюу арваннэгдүгээр сарын 18-нд болсон ээлжит хуралдаанаар мэдээллээ. Үүнээс 574.7 мянган тонн үр тариа, үүнээс 519.7 мянган тонн улаанбуудай, 171.4 мянган тонн төмс, 204.8 мянган тонн хүнсний ногоо, 394.3 мянган тонн тэжээлийн ургамал, 57.6 мянган тонн тосны ургамал тус тус хураан авсан байна.\n\nХүнс, хөдөө аж ахуй, хөнгөн үйлдвэрийн сайд Ц.Идэрбат тариалангийн үйлдвэрлэл эрхлэгчдэд олгох хөнгөлөлттэй зээлийн хүртээмжийг нэмэгдүүлэхээр ажиллаж байгаа гэж мэдэгдлээ. Тариаланч аж ахуйн нэгжүүдэд дизель түлшийг литр тутмыг нь 3,400 төгрөгөөр нийлүүлсэн байна.\n\nИрэх оны тариалалтын бэлтгэл ажлыг эртнээс хангаж, шатахуун, үр тариа, төмс, хүнсний ногоо, тэжээлийн таримлын үрийн нөөцийг бүрдүүлэхэд онцгойлон анхаарна гэж сайд мэдэгдлээ. Тариалангийн салбар нь Монгол Улсын хүнсний хангамж, хөдөөгийн эдийн засгийн чухал хэсэг бөгөөд ургацын хэмжээ нь дотоодын хүнсний үнэ, хангамжид шууд нөлөөлдөг.\n\nУргац хураалтын дүн нь өнгөрсөн жилүүдтэй харьцуулахад тариалангийн үйлдвэрлэл тогтвортой байгааг харуулж байна. Засгийн газар тариаланчдад дэмжлэг үзүүлэх, техник тоног төхөөрөмж, үрийн хангамжийг сайжруулах чиглэлээр ажиллаж байгаа юм.", textEn:"The preliminary results of the 2026 harvest show that 1.4 million tonnes of crops were gathered nationwide, the Government said at its regular meeting yesterday, November 18. Of this, 574,700 tonnes were grain, including 519,700 tonnes of wheat, along with 171,400 tonnes of potatoes, 204,800 tonnes of vegetables, 394,300 tonnes of fodder crops and 57,600 tonnes of oil crops.\n\nMinister of Food, Agriculture and Light Industry Ts. Iderbat said work is under way to expand access to concessional loans for farming enterprises. Diesel fuel was supplied to farming enterprises at 3,400 tugriks a litre.\n\nThe minister said special attention will be paid to preparing early for next year's sowing and building up reserves of fuel and seed for grain, potatoes, vegetables and fodder crops. Farming is a vital part of Mongolia's food supply and rural economy, and the size of the harvest directly affects domestic food prices and availability.\n\nThe harvest figures show that crop production remains stable compared with recent years. The Government is working to support farmers and improve supplies of machinery, equipment and seed."},
  {id:8, cat:"delhii", title:"Трамп, Си Жиньпин, Путин нар Шэньжэньд түүхэнд анх удаа гурван талт уулзалт хийнэ", titleEn:"Trump, Xi and Putin to hold first-ever trilateral meeting in Shenzhen", time:"30 мин", timeEn:"30 min", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Skyline%20in%20Shenzhen%20%2820250327%29.jpg?width=760", text:"АНУ-ын Ерөнхийлөгч Дональд Трамп, БНХАУ-ын дарга Си Жиньпин, ОХУ-ын Ерөнхийлөгч Владимир Путин нар өнөөдөр буюу арваннэгдүгээр сарын 19-нд Хятадын Шэньжэнь хотод түүхэнд анх удаа гурван талт уулзалт хийнэ. Уулзалт нь Ази, Номхон далайн эдийн засгийн хамтын ажиллагааны буюу АПЕК-ийн дээд хэмжээний уулзалтын хажуугаар болох бөгөөд Хятадын Гадаад хэргийн яам арваннэгдүгээр сарын 16-нд үүнийг баталсан байна.\n\nАПЕК-ийн 33 дахь удаагийн удирдагчдын уулзалт арваннэгдүгээр сарын 18-19-нд Шэньжэньд болж байгаа бөгөөд 21 эдийн засгийн удирдагчид оролцож байна. Хятад улс АПЕК-ийг 12 жилийн дараа анх удаа даргалж байгаа юм. Гурван удирдагчийн уулзалт нь дэлхийн хамгийн хүчирхэг гурван цөмийн гүрний тэргүүн нарын анхны гурван талт уулзалт болох юм.\n\nТрамп Ерөнхийлөгч уулзалтаар цөмийн зэвсгийг хорогдуулах, Ирантай хийж буй дайн, хиймэл оюун ухаан зэрэг асуудлыг хэлэлцэхээр төлөвлөж байна. Харин АНУ-ын албан тушаалтнуудын мэдээлснээр Украинд хийж буй Оросын дайн хэлэлцэх сэдэвт орохгүй бөгөөд ямар нэгэн тохиролцоонд хүрэх хүлээлт бага, уулзалт нь агуулгаас илүү бэлгэдлийн шинжтэй байх төлөвтэй байна. Трамп, Путин хоёр тусдаа хоёр талт уулзалт хийхгүй аж.\n\nӨчигдөр болсон АПЕК-ийн дээд хэмжээний уулзалтын үеэр Си Жиньпин худалдааны протекционизмыг зогсоож, чөлөөт, нээлттэй худалдааг дэмжихийг уриалсан бол Путин барууны хориг арга хэмжээг шүүмжилжээ. Си Жиньпин Трампыг нисэх буудалд биечлэн угтан авсан нь есдүгээр сард Хятадын удирдагч Вашингтон хотод төрийн айлчлал хийх үеэр Трамп үзүүлсэн хүндэтгэлийн хариу болсон байна. Зарим хэвлэл уулзалтыг 1945 оны Ялтын бага хуралтай зүйрлэж байгаа ч түүхчид энэ зүйрлэл нь төөрөгдүүлсэн, аюултай гэж анхааруулж байна.", textEn:"US President Donald Trump, Chinese President Xi Jinping and Russian President Vladimir Putin will hold the first-ever trilateral meeting today, November 19, in Shenzhen, China. The meeting takes place on the sidelines of the Asia-Pacific Economic Cooperation, APEC, summit, and China's Foreign Ministry confirmed it on November 16.\n\nThe 33rd APEC Economic Leaders' Meeting is being held in Shenzhen on November 18-19, with the leaders of 21 economies attending. China is chairing APEC for the first time in 12 years. The three leaders' meeting will be the first trilateral summit of the heads of the world's three most powerful nuclear states.\n\nPresident Trump plans to discuss reducing nuclear arsenals, the war with Iran and artificial intelligence at the meeting. US officials say Russia's war in Ukraine will not be on the agenda, expectations of any agreement are low, and the meeting is likely to be heavier in symbolism than substance. Trump and Putin will not hold a separate bilateral meeting.\n\nAt the APEC summit yesterday, Xi Jinping urged an end to trade protectionism and support for free and open trade, while Putin criticised Western sanctions. Xi personally greeted Trump at the airport, reciprocating the gesture Trump made during the Chinese leader's state visit to Washington in September. Some media have compared the meeting with the 1945 Yalta Conference, but historians warn that the comparison is misleading and dangerous."},
  {id:9, cat:"delhii", title:"Персийн булангийн орнууд Ираны дроны довтолгоог няцаав", titleEn:"Gulf states repel Iranian drone attacks", time:"45 мин", timeEn:"45 min", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Khalig-fars-Persian-Gulf%2001.jpg?width=760", text:"Персийн булангийн орнууд өчигдөр буюу арваннэгдүгээр сарын 18-нд Иран болон түүний Йемен дэх холбоотон Хуси бүлэглэлийн пуужин, дроны довтолгоог няцаав. Довтолгоо нь АНУ Хормузын хоолойд орших Ираны Кешм арал дахь пуужин хөөргөх байгууламж руу цохилт өгсний дараа гарсан бөгөөд есөн сар үргэлжилж буй дайныг зогсоох оролдлого үргэлжилж байгаа ч мөргөлдөөн улам ширүүсч байна.\n\nКувейтийн арми өнөө өглөө агаарын довтолгооноос хамгаалах систем нь дайсны дроны довтолгоог няцааж байгаа гэж мэдэгдсэн бөгөөд Ираны арми Кувейт дэх Али Аль-Салем агаарын бааз дахь АНУ-ын дрон, пуужингийн байгууламжийг онилсон гэж мэдэгджээ. Энэ нь Кувейтэд есдүгээр сараас хойших анхны Ираны довтолгоо болсон байна. Кувейт довтолгоог «аюултай хурцадмал байдал» гэж буруутгасан байна.\n\nХөрш Бахрейн мөн лхагва гарагийн өглөө Ираны агаарын довтолгоог няцаасан гэж мэдэгдсэн бөгөөд энэ нь тус улсад энэ долоо хоногт гарсан гурав дахь довтолгоо болсон байна. Бахрейн нь АНУ-ын Тэнгисийн цэргийн Тавдугаар флотын бааз байрладаг улс бөгөөд дайны эхэн үед ихээхэн довтолгоонд өртөж байсан ч сүүлийн долоо хоногуудад довтолгоо зогссон байсан юм.\n\nҮүний зэрэгцээ Йемен дэх Хуси бүлэглэлтэй тэмцэж буй Саудын Арабаар удирдуулсан эвсэл тус бүлэглэлээс Саудын Арабын нийслэл Эр-Рияд чиглэн харвасан далавчит пуужинг устгасан гэж мэдэгдсэн байна. Египет, Катар, Саудын Араб, Арабын Нэгдсэн Эмират улс тус бүр Бахрейн руу хийсэн Ираны довтолгоог буруутгаж, тус улсын бүрэн эрхт байдал, аюулгүй байдалд заналхийлж байна гэж мэдэгдсэн байна. Катар, Оман улс Тегерантай зуучлалын хэлэлцээ хийж байгаа аж.", textEn:"Gulf states yesterday, November 18, repelled missile and drone attacks from Iran and its Houthi allies in Yemen. The attacks came after the United States struck a missile launch site on Iran's Qeshm Island in the Strait of Hormuz, and fighting is intensifying even as efforts continue to end the nine-month-old war.\n\nKuwait's army said this morning that its air defences were countering hostile drone attacks, and the Iranian army said its drones had targeted US drone and missile installations at Ali Al-Salem Air Base in Kuwait. It was the first Iranian attack on Kuwait since September. Kuwait condemned the attack as a «dangerous escalation».\n\nNeighbouring Bahrain also said it intercepted Iranian aerial attacks on Wednesday morning, the third attack on the country this week. Bahrain hosts the US Navy's Fifth Fleet and was heavily targeted early in the war, although attacks had stopped in recent weeks.\n\nAt the same time, the Saudi-led coalition fighting the Houthis in Yemen said it had destroyed a cruise missile launched by the group toward the Saudi capital, Riyadh. Egypt, Qatar, Saudi Arabia and the United Arab Emirates each condemned Iran's attack on Bahrain, calling it a violation of Bahrain's sovereignty and a threat to its security and stability. Qatar and Oman are pursuing mediation talks with Tehran."},
  {id:10, cat:"delhii", title:"Украин Оросын хоёр нефть боловсруулах үйлдвэрийг онилж, Зеленский дотоодын зэвсгээ магтлаа", titleEn:"Ukraine hits two Russian refineries as Zelenskyy hails home-made weapons", time:"1 цаг", timeEn:"1 hour", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Altona%20oil%20refinery%202.jpg?width=760", text:"Украин өчигдөр буюу арваннэгдүгээр сарын 18-нд Оросын өмнөд хэсгийн хоёр нефть боловсруулах үйлдвэрт шинэ цохилт өгсөн тухай тус улсын албан тушаалтнууд мэдэгдлээ. Үүний зэрэгцээ Украины Ерөнхийлөгч Володимир Зеленский Крымийг Орост холбосон Керчийн гүүрийг гэмтээсэн дотооддоо үйлдвэрлэсэн зэвсгийн үр нөлөөг магтсан байна.\n\nУкраины Жанжин штабын мэдээлснээр Краснодар хязгаар дахь Ильскийн нефть боловсруулах үйлдвэрийн агуулах савнууд, Афипскийн үйлдвэрийн боловсруулах хэсэгт цохилт өгсөн байна. Хоёр үйлдвэр нь ням гарагийн шөнө ч мөн онилогдсон бөгөөд жилд нийт 95 сая баррель орчим нефть боловсруулж, Украины өмнөд болон зүүн фронт дахь Оросын цэргийг түлшээр хангадаг гэж мэдэгдсэн байна.\n\nОросын албан тушаалтнууд бүс нутгийн хоёр аж үйлдвэрийн байгууламжид гал гарсан тухай мэдээлсэн боловч дэлгэрэнгүй мэдээлэл өгөөгүй байна. Северский дүүрэгт гал гарч, дөрвөн хүн гэмтсэн гэж мэдээлжээ. Хохирлын хэмжээг бие даан баталгаажуулаагүй байна.\n\nЗеленский Керчийн гүүр рүү хийсэн довтолгоог «өмнө нь байгаагүй» ажиллагаа гэж нэрлэж, Украины холын зайн дрон, пуужинг хэдэн долоо хоногийн турш бэлтгэсэн томоохон ажиллагаанд ашигласан гэж мэдэгдлээ. Тэрбээр «Манай технологи, компаниуд маш сайн хөгжиж байна» гэж сошиал сүлжээнд бичсэн байна. Үүний зэрэгцээ Орос Одесса хотын орон сууцны хороолол руу дроны довтолгоо хийж, хэд хэдэн хүн амиа алдсан гэж Зеленский мэдэгдлээ.", textEn:"Ukraine carried out new strikes on two oil refineries in southern Russia yesterday, November 18, Ukrainian officials said. At the same time, Ukrainian President Volodymyr Zelenskyy praised the effectiveness of domestically produced weapons that damaged the Kerch Bridge linking Russia to the occupied Crimean Peninsula.\n\nUkraine's General Staff said storage tanks were hit at the Ilsky refinery and a processing unit was struck at the Afipsky refinery, both in Russia's Krasnodar region. The two refineries, which were also targeted on Sunday night, can process around 95 million barrels of oil a year and supply Russian forces on the front line in southern and eastern Ukraine, it said.\n\nRussian officials reported fires at two industrial facilities in the region but gave no details. Fires were reported in the Seversky district, where both refineries are located, and four people were injured. The extent of any damage has not been independently verified.\n\nZelenskyy called the attack on the Kerch Bridge an «unprecedented» operation, saying Ukraine's long-range drones and missiles were deployed in a large-scale attack prepared over weeks. «Our technologies and companies are developing very well,» he wrote on social media. At the same time, Zelenskyy said Russia had launched drone attacks on a residential area in Odesa, killing several people."},
  {id:11, cat:"delhii", title:"Оросын Ан-12 цэргийн тээврийн онгоц Сибирьт осолдож, 19 хүн амиа алдлаа", titleEn:"Russian An-12 military transport plane crashes in Siberia, killing 19", time:"1 цаг", timeEn:"1 hour", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Antonov%20An-12%209L-LEC%20at%20Baghdad.jpg?width=760", text:"Оросын Ан-12 цэргийн тээврийн онгоц мягмар гарагт буюу арваннэгдүгээр сарын 17-нд Сибирийн Кемерово мужид осолдож, онгоцонд байсан 19 хүн бүгд амиа алдсан тухай Оросын Батлан хамгаалах яам мэдэгдлээ. Онгоц нь хүн амгүй бүс нутагт, Москва хотоос зүүн тийш 3000 орчим километрийн зайд орших Ягуново тосгоны ойролцоо унасан байна.\n\nОнгоц нь Новосибирск хотын Толмачево нисэх онгоцны буудлаас Красноярск хязгаар дахь Канск агаарын бааз руу хийх хуваарьт нислэг хийж явсан бөгөөд багийн гишүүд, цэргүүд болон сэлбэг хэрэгсэл тээвэрлэж явсан гэж мэдээлжээ. Ослын урьдчилсан шалтгаан нь техникийн гэмтэл гэж Батлан хамгаалах яам мэдэгдсэн байна.\n\nКемерово мужийн захирагч Илья Середюк ослыг баталж, ослын газарт гарсан галыг яаралтай тусламжийн багууд унтраасан гэж мэдэгдлээ. Оросын Сансар-агаарын хүчний комисс ослын газарт ажиллаж, ослын бүх нөхцөл байдлыг тогтоож байгаа бөгөөд Оросын Мөрдөн шалгах хороо нислэгийн аюулгүй байдлын дүрэм зөрчсөн байж болзошгүй асуудлаар эрүүгийн хэрэг үүсгэсэн байна.\n\nАн-12 нь 1950-иад оны сүүлээс үйлчилгээнд байгаа Зөвлөлтийн дөрвөн хөдөлгүүртэй турбопроп тээврийн онгоц юм. Ослын талаарх анхны мэдээллүүдэд амиа алдсан хүний тоог 17 гэж мэдээлж байсан бол Батлан хамгаалах яам 19 гэж тодруулсан байна. Ослын яг шалтгааныг тогтоох мөрдөн шалгах ажиллагаа үргэлжилж байна.", textEn:"A Russian An-12 military transport plane crashed in the Kemerovo region of Siberia on Tuesday, November 17, killing all 19 people on board, Russia's Defence Ministry said. The aircraft came down in an unpopulated area near the village of Yagunovo, about 3,000 kilometres east of Moscow.\n\nThe aircraft was on a scheduled flight from Tolmachevo Airport in Novosibirsk to Kansk Air Base in Krasnoyarsk Krai, carrying crew members, soldiers and spare parts, according to reports. The Defence Ministry said a technical malfunction was the preliminary cause of the crash.\n\nKemerovo region governor Ilya Seredyuk confirmed the crash and said emergency teams had quickly extinguished a fire at the site. A commission from the Russian Aerospace Forces is working at the crash site to establish all the circumstances, and Russia's Investigative Committee has opened a criminal case into possible violations of flight safety rules.\n\nThe An-12 is a Soviet-built four-engine turboprop transport aircraft that has been in service since the late 1950s. Early reports put the death toll at 17, but the Defence Ministry later put it at 19. The investigation into the exact cause of the crash is under way."},
  {id:12, cat:"delhii", title:"GTA VI дэлхий даяар худалдаанд гарч, тоглогчид Вайс Ситид орлоо", titleEn:"GTA VI launches worldwide as gamers enter Vice City", time:"2 цаг", timeEn:"2 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Miami%20skyline%20from%20the%20ocean.jpg?width=760", text:"Түүхэн дэх хамгийн их хүлээлттэй видео тоглоом болох «Grand Theft Auto VI» өнөөдөр буюу арваннэгдүгээр сарын 19-нд дэлхий даяар худалдаанд гарч эхэллээ. Тоглоом нь Шинэ Зеландад шөнө дунд хүрэхэд нээгдэж, цагаар дамжин дэлхий даяар нээгдэж байгаа бөгөөд тоглогчид Вайс Ситид орж байна.\n\nТоглоомыг Rockstar Games компани бүтээсэн бөгөөд Sony-ийн PlayStation 5, Microsoft-ийн Xbox Series X болон S консол дээр тоглох боломжтой. Стандарт хувилбарын үнэ АНУ-д 79.99 ам.доллар байна. Компьютер дээр тоглох хувилбар одоогоор гараагүй бөгөөд Rockstar Games компьютерт зориулсан хувилбарын огноог зарлаагүй байна.\n\nҮйл явдал нь Флорида мужаас сэдэвлэсэн Леонида хэмээх зохиомол муж, Майами хотоос сэдэвлэсэн Вайс Ситид өрнөх бөгөөд тоглогчид Лусиа Каминос, Жэйсон Дювал хэмээх хоёр гол дүрийн хооронд шилжин тоглоно. Тоглоомын гол хэсгийг дуусгахад 50 орчим цаг зарцуулагдах тооцоотой байна. Тоглоомын файлын хэмжээ 212 гигабайт хүртэл байх бөгөөд урьдчилан татаж авах ажиллагаа арваннэгдүгээр сарын 10-нд эхэлсэн юм.\n\nЭнэ нь 2013 онд гарсан «Grand Theft Auto V»-ийн дараах 13 жилийн дараа гарч буй цувралын шинэ анги бөгөөд үйлдвэрлэлийн зардал нь 1 тэрбум ам.доллар болон түүнээс дээш гэж тооцоологдож байна. Sensor Tower аналитик фирмийн тооцоолсноор арваннэгдүгээр сарын 17-ны байдлаар 16 сая орчим хувь зарагдаж, 1.5 тэрбум гаруй ам.долларын орлого олсон байна. GTA Online горим нь 2027 онд тусдаа шинэчлэлтээр гарах төлөвтэй байна.", textEn:"The most anticipated video game release in history, «Grand Theft Auto VI», began its global rollout today, November 19. The game unlocked at midnight in New Zealand and is opening around the world as the clock turns, with gamers entering Vice City.\n\nThe game, made by Rockstar Games, is available on Sony's PlayStation 5 and Microsoft's Xbox Series X and S consoles. The standard edition costs 79.99 US dollars in the United States. There is no PC version at launch, and Rockstar Games has not announced a PC release date.\n\nThe action takes place in Leonida, a fictional state inspired by Florida, and Vice City, a fictional version of Miami, with play switching between two leading characters, Lucia Caminos and Jason Duval. The main part of the game is estimated to take around 50 hours to complete. The game file is up to 212 gigabytes, and pre-loading began on November 10.\n\nIt is the first new instalment in the series in 13 years, following «Grand Theft Auto V» in 2013, with production costs estimated at 1 billion US dollars or more. Analytics firm Sensor Tower estimates that close to 16 million copies had been sold for more than 1.5 billion dollars as of November 17. The GTA Online mode is expected to arrive as a separate update in 2027."},
  {id:13, cat:"tech", title:"«Вояжер-1» сансрын хөлөг Дэлхийгээс гэрлийн нэг өдрийн зайд хүрлээ", titleEn:"Voyager 1 reaches one light-day from Earth", time:"2 цаг", timeEn:"2 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Voyager%20spacecraft.jpg?width=760", text:"НАСА-гийн «Вояжер-1» сансрын хөлөг өчигдөр буюу арваннэгдүгээр сарын 18-ны 05:16 цагт /Зүүн Америкийн цагаар/ Дэлхийгээс гэрлийн нэг өдрийн зайд хүрч, хүн төрөлхтний бүтээсэн анхны биет болж, ийм хол зайд очлоо. Тэр үед хөлөг нь Дэлхийгээс 25.9 тэрбум километр буюу 16.1 тэрбум милийн зайд байсан гэж НАСА-гийн Тийрэлтэт хөдөлгүүрийн лабораторийн тооцоолол харуулжээ.\n\nГэрлийн нэг өдөр гэдэг нь гэрэл 24 цагийн дотор туулах зай бөгөөд одооноос Дэлхийгээс илгээсэн радио дохио «Вояжер-1»-д хүрэхэд бүтэн өдөр зарцуулагдах бөгөөд хариу нь бас нэг өдөр шаардагдана. НАСА-гийн захирагч Жаред Айзекман «Вояжер-1 одоо Дэлхийгээс гэрлийн нэг өдрийн зайд байна. Энэ бол хүний гараар бүтээгдсэн, бараг 50 жилийн өмнө хөөргөсөн сансрын хөлгийн хувьд ер бусын амжилт» гэж мэдэгдсэн байна.\n\n«Вояжер-1» 1977 оны есдүгээр сарын 5-нд Флорида мужийн Канаверал хошуунаас хөөрсөн бөгөөд Бархасбадь, Санчир гаригийг судлах анхны даалгаврыг гүйцэтгэсний дараа 2012 оны наймдугаар сард гелиопаузыг давж, од хоорондын орон зайд орсон анхны хүн төрөлхтний бүтээсэн биет болсон юм. Хөлөг одоо Нартай харьцуулахад цагт 61,000 километр хурдтайгаар хөдөлж байна.\n\nХөлгийн анхны 10 багаж хэрэгслийн 8 нь ажиллахаа больсон бөгөөд плутони-238 эрчим хүчний эх үүсвэрийн хүч жил бүр бага зэрэг буурч байна. НАСА хөлөг 2030-аад оны эхэн хүртэл холбоо барьж байх боломжтой гэж таамаглаж байна. «Вояжер-2» хөлөг гэрлийн нэг өдрийн зайд 2035 оны арваннэгдүгээр сард хүрэх төлөвтэй байна. «Вояжер-1» нь 40,000 орчим жилийн дараа Глизе 445 одны 1.7 гэрлийн жилийн дотор өнгөрөх төлөвтэй байна.", textEn:"NASA's Voyager 1 spacecraft reached a distance of one light-day from Earth yesterday, November 18, at 05:16 Eastern Standard Time, becoming the first human-made object to travel so far into space. At that point it was about 25.9 billion kilometres, or 16.1 billion miles, from Earth, according to calculations by NASA's Jet Propulsion Laboratory.\n\nOne light-day is the distance light travels in 24 hours, and from now on a radio signal sent from Earth takes a full day to reach Voyager 1, with another day required for a reply to return. NASA Administrator Jared Isaacman said: «Voyager 1 is now one light-day from Earth, an extraordinary NASA achievement for a spacecraft assembled by human hands and launched nearly 50 years ago.»\n\nVoyager 1 launched on September 5, 1977, from Cape Canaveral, Florida, and after completing its original mission to explore Jupiter and Saturn, it crossed the heliopause in August 2012, becoming the first human-made object to enter interstellar space. The spacecraft is now travelling at about 61,000 kilometres per hour relative to the Sun.\n\nEight of its original 10 instruments have stopped working, and the output from its plutonium-238 power source degrades a little each year. NASA estimates the spacecraft may keep communicating into the early 2030s. Voyager 2 is expected to reach the one-light-day distance in November 2035. Voyager 1 is expected to pass within about 1.7 light-years of the star Gliese 445 in about 40,000 years."},
  {id:14, cat:"tech", title:"Nvidia Хятадад хиймэл оюуны чип борлуулах ажлаа зогсоов", titleEn:"Nvidia pulls plug on China AI chip sales amid US export scrutiny", time:"3 цаг", timeEn:"3 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/NVIDIA%20Headquarters.jpg?width=760", text:"Nvidia компани АНУ-ын экспортын хяналтын хүрээнд Хятадад хиймэл оюуны чип борлуулах ажлаа зогсоолоо. Энэ шийдвэр нь АНУ, Хятадын технологийн өрсөлдөөн ширүүсч, Вашингтоны экспортын хязгаарлалт чангарч байгаа үед гарсан байна.\n\nЭнэ нь тус компанийн хувьд хүнд долоо хоногийн дараа гарсан шийдвэр юм. Nvidia-ийн үүсгэн байгуулагч Женсен Хуан арваннэгдүгээр сарын 12-нд гэр бүлээс гадуурх харилцааны талаарх мэдээллүүдийн дараа гүйцэтгэх захирлын албан тушаалаасаа огцорсон бөгөөд санхүүгийн захирал Колетт Кресс түр гүйцэтгэх захирлаар ажиллаж байна. Төлөөлөн удирдах зөвлөл байнгын залгамжлагчийг хайж байгаа бөгөөд мэдээллээр зөвлөл Хуаныг эргэн ирэх асуудлыг хэлэлцэхгүй байгаа аж.\n\nХуан арваннэгдүгээр сарын 17-нд компанийн төлөөлөн удирдах зөвлөл хүсвэл гүйцэтгэх захирлын албан тушаалд эргэн ирэхэд бэлэн байгаагаа мэдэгдсэн байна. АНУ-ын Ерөнхийлөгч Дональд Трамп даваа гарагт Хуаныг эргэн ирэхэд «таагүйцэхгүй» гэж мэдэгдсэн бол Сангийн сайд Скотт Бессент компанийн хяналтын соёлд санаа зовниж, гаднаас хүн томилох шаардлагатай гэж мэдэгджээ. Хуаныг эргэн ирэхийг уриалсан нээлттэй захидалд Nvidia-ийн 10 мянга гаруй одоогийн болон хуучин ажилтан гарын үсэг зурсан байна.\n\nХятадын зах зээл нь Nvidia-ийн хувьд чухал байсан бөгөөд экспортын хяналт нь тус компанийн борлуулалт, дэлхийн хиймэл оюуны чипийн нийлүүлэлтийн сүлжээнд нөлөөлж байна. Тус компанийн хувьцаа дуулиан дэгдсэнээс хойш зах зээлийн үнэлгээгээрээ 700 тэрбум ам.доллараар буурсан бөгөөд шинжээчид тус компанийн цаашдын удирдлага, Хятадын зах зээл дэх байр суурийг анхааралтай ажиглаж байна.", textEn:"Nvidia has stopped selling artificial intelligence chips in China amid US export scrutiny. The decision comes as technological rivalry between the United States and China intensifies and Washington's export controls tighten.\n\nIt follows a difficult week for the company. Nvidia co-founder Jensen Huang stepped down as chief executive on November 12 following reports of extramarital affairs, and Chief Financial Officer Colette Kress is serving as interim CEO. The board is searching for a permanent successor and, according to reports, is not considering Huang's return.\n\nHuang said on November 17 that he would return as chief executive if the company's board asked him to. US President Donald Trump said on Monday that he «would not mind» Huang returning, while Treasury Secretary Scott Bessent said an outsider should be appointed, citing concerns about the company's compliance culture. An open letter calling for Huang's return has been signed by more than 10,000 current and former Nvidia employees.\n\nThe Chinese market has been important for Nvidia, and export controls are affecting the company's sales and the global supply chain for AI chips. The company's market value has fallen by 700 billion US dollars since the scandal broke, and analysts are watching its future leadership and its position in the Chinese market closely."},
  {id:15, cat:"sport", title:"Жүдо бөхийн залуучуудын ДАШТ өнөөдөр Ташкентэд эхэллээ — Монголоос 18 тамирчин оролцоно", titleEn:"Youth judo world championships begin in Tashkent today; 18 Mongolians compete", time:"3 цаг", timeEn:"3 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/A%20judo%20competition%20%28FL61746686%29.jpg?width=760", text:"Узбекистан Улсын Ташкент хотноо жүдо бөхийн залуучуудын дэлхийн аварга шалгаруулах тэмцээн өнөөдөр буюу арваннэгдүгээр сарын 19-нд эхэлж, арваннэгдүгээр сарын 22-ныг хүртэл үргэлжилнэ. Тэмцээнд 82 орны эрэгтэй 319, эмэгтэй 276, нийт 595 жүдоч оролцохоор мэдүүлэг өгчээ.\n\nМонгол Улсаас эрэгтэй, эмэгтэй тус бүр есөн жүдоч оролцоно. Эрэгтэйчүүдийн 60 кг-ын жинд Б.Бат-Энэрэл, О.Төгөлдөр, 66 кг-д Б.Тэмүүжин, 73 кг-д Ц.Мишигтогоо, 81 кг-д Г.Түвдэнренчин, 90 кг-д А.Оджавхлан, Д.Ууганбилэг, -100 кг-д У.Мөнгөн-Учрал, +100 кг-д М.Тэмүүлэн нар барилдана.\n\nЭмэгтэйчүүдээс 48 кг-д Ж.Анударь, Л.Булган, 52 кг-д Л.Саяжаргал, 57 кг-д Т.Ариунзаяа, Б.Батсувд, 63 кг-д Х.Маралмаа, Х.Ариунтунгалаг, -78 кг-д Э.Буян-Өлзий, +78 кг-д Ж.Анар нар барилдах юм. Монголын баг тамирчид арваннэгдүгээр сарын 17-нд Ташкентыг зорисон бөгөөд Төв аймгийн Батсүмбэр суманд байрлах «Чэмпионс Чэмп» баазад бэлтгэлээ базаасан байна.\n\nЗалуучуудын ДАШТ-ээс гавьяат тамирчин Ө.Дүүрэнбаяр, олон улсын хэмжээний мастер Л.Сосорбарам нар алтан медаль хүртэж байсан түүхтэй. Монголын жүдочид энэ удаагийн тэмцээнд медалийн төлөө өрсөлдөх бөгөөд багийг «Чэмпионс Чэмп» бааз болон «Батсол» компанийн захирал Н.Батсайхан ахалж байна.", textEn:"The Youth Judo World Championships begin today, November 19, in Tashkent, Uzbekistan, and run until November 22. A total of 595 judoka from 82 countries — 319 men and 276 women — have entered.\n\nMongolia is represented by nine men and nine women. In the men's events, B. Bat-Enerel and O. Tuguldur compete at 60 kg, B. Temuujin at 66 kg, Ts. Mishigtogoo at 73 kg, G. Tuvdenrenchin at 81 kg, A. Odjavkhlan and D. Uuganbileg at 90 kg, U. Mungun-Uchral at under 100 kg and M. Temuulen at over 100 kg.\n\nFor the women, J. Anudari and L. Bulgan compete at 48 kg, L. Sayajargal at 52 kg, T. Ariunzayaa and B. Batsuvd at 57 kg, Kh. Maralmaa and Kh. Ariuntungalag at 63 kg, E. Buyan-Ulzii at under 78 kg and J. Anar at over 78 kg. The Mongolian team travelled to Tashkent on November 17 after training at the Champions Camp base in Batsumber soum, Tuv aimag.\n\nMongolia has a proud record at the youth world championships, where honoured athlete U. Duurenbayar and international master L. Sosorbaram have won gold medals. The Mongolian judoka will be competing for medals this time, with the team led by N. Batsaikhan, director of the Champions Camp base and the Batsol company."},
  {id:16, cat:"sport", title:"Сүмогийн дөрвөн дивизионд Монгол бөхчүүд тэргүүлж байна", titleEn:"Mongolian wrestlers lead in all four professional sumo divisions", time:"3 цаг", timeEn:"3 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Sumo%20wrestlers.jpg?width=760", text:"Японы Фүкүока хотын Олон улсын төвд болж буй Кюсю башё буюу мэргэжлийн сүмогийн тэмцээний арав дахь өдөр арваннэгдүгээр сарын 17-нд өндөрлөлөө. Дээд дивизионы бүх дөрвөн шатанд Монгол бөхчүүд тэргүүлж байгаа нь олны анхаарлыг татаж байна.\n\nДээд зиндааны макуүчи дивизионд есөн ялалт, нэг ялагдалтайгаар сэкивакэ Атамифүжи, маэгашира Вакамотохарү нар тэргүүлж байна. Тэднээс нэг ялалтаар хоцорч буй ёкозүна Оносато, озэки Киришима, маэгашира Кинбозан /Казахстан/, Дэванорю Т.Тэмүүлэн /Монгол/ нар удаалж байна.\n\nЁкозүна Хошёорюү С.Бямбасүрэн тав дахь ялалтаа авсан бол Тамаваши Б.Мөнх-Оргил долоон ялалттай тэмцээнийг үргэлжлүүлж байна. Озэки Киришима Б.Лхагвасүрэн Украины бөх Аонишикид ялагдаж, тэмцээнд хоёр дахь ялагдлаа хүлээсэн байна. Дээд зиндаанд барилдаж буй есөн Монгол бөх бүгд тэмцээний эцэст эерэг баланс буюу качикосид хүрэх магадлал өндөр байгаа аж.\n\nХоёрдугаар дивизионы жюрёод Тамашёхо Э.Энхманлай өмнө нь ялагдалгүй явж байсан ч Энход ялагдаж, анхны ялагдлаа хүлээсэн байна. Харин доод дивизионуудад Ваканофүжи Т.Бухчулуун санданмэ дивизионд таван ялалттай ялагдалгүй явж байгаа бол Жёошёоюү А.Сосорхуу жёнидан дивизионд мөн таван ялалттай байна.", textEn:"The tenth day of the Kyushu basho professional sumo tournament ended on November 17 at the Fukuoka International Centre in Japan. Mongolian wrestlers are leading in all four divisions of the top ranks, drawing wide attention.\n\nIn the top makuuchi division, sekiwake Atamifuji and maegashira Wakamotoharu lead with nine wins and one loss. One win behind them are yokozuna Onosato, ozeki Kirishima, maegashira Kinbozan of Kazakhstan and Dewanoumi's T. Temuulen of Mongolia.\n\nYokozuna Hoshoryu S. Byambasuren has earned his fifth win, while Tamawashi B. Munkh-Orgil continues the tournament with seven wins. Ozeki Kirishima B. Lkhagvasuren lost to Ukrainian wrestler Aonishiki, his second defeat of the tournament. All nine Mongolian wrestlers in the top division are very likely to finish with a winning record, or kachi-koshi.\n\nIn the second-tier juryo division, Tamashoho E. Enkhmanlai, who had been undefeated, suffered his first loss, to Enho. In the lower divisions, Wakanofuji T. Bukhchuluun continues undefeated with five wins in sandanme, while Joshoryu A. Sosorkhuu has also won five in jonidan."},
  {id:17, cat:"sport", title:"П.В.Синдху дэлхийн чансааны топ-5-д дөрвөн жилийн дараа эргэн орлоо", titleEn:"PV Sindhu returns to world top five after four years", time:"3 цаг", timeEn:"3 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Badminton%20player%20%281%29.jpg?width=760", text:"Энэтхэгийн бадминтоны од П.В.Синдху Дэлхийн бадминтоны холбооны чансаанд нэг байраар дээшилж, тавдугаар байрт орж, дөрвөн жилийн дараа дэлхийн топ-5-д эргэн орлоо. Энэ нь түүний карьер дахь чухал эргэлт гэж спортын хэвлэлүүд тэмдэглэж байна.\n\nСиндху нь Энэтхэгийн хамгийн алдартай бадминтончдын нэг бөгөөд олимп, дэлхийн аварга шалгаруулах тэмцээнүүдэд медаль хүртсэн туршлагатай тамирчин юм. Сүүлийн жилүүдэд бэртэл, формтой холбоотой асуудал тулгарч байсан ч тэрбээр тогтвортой тоглолтоороо чансаагаа дахин дээшлүүлж байна.\n\nБадминтон нь Азийн орнуудад хамгийн их үзэгчтэй спортын нэг бөгөөд Энэтхэг, Хятад, Индонез, Япон, Солонгосын тамирчид дэлхийн чансааг тэргүүлдэг. Синдхугийн топ-5-д эргэн орсон нь Энэтхэгийн бадминтоны шинэ үеийн тамирчдад урам зориг өгч байна.\n\nҮүний зэрэгцээ Энэтхэгийн крикетийн шигшээ баг Шинэ Зеландын эсрэг эхний тест тоглолтоо өнөөдөр Веллингтонд эхлүүлж байна. Энэтхэгийн спорт сонирхогчид энэ долоо хоногт бадминтон, крикетийн хоёр том үйл явдлыг дагаж байна.", textEn:"Indian badminton star P.V. Sindhu has moved up one spot to number five in the Badminton World Federation rankings, returning to the world top five after four years. Sports media describe it as an important turning point in her career.\n\nSindhu is one of India's best-known badminton players, with medals at the Olympics and World Championships. Although she has faced injuries and form problems in recent years, she has climbed the rankings again with consistent performances.\n\nBadminton is one of the most watched sports in Asia, and players from India, China, Indonesia, Japan and South Korea lead the world rankings. Sindhu's return to the top five is an inspiration to the new generation of Indian badminton players.\n\nAt the same time, India's cricket team begins its first Test match against New Zealand today in Wellington. Indian sports fans are following two major events this week, in badminton and cricket."},
  {id:18, cat:"soyol", title:"«Тэнгэрийн хүү» жүжгийг үзэгчдийн хүсэлтээр дахин тоглоно", titleEn:"'Son of Heaven' play returns by popular demand", time:"3 цаг", timeEn:"3 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/783%203%20%28%2B%203%29%20dancers%20performing%20on%20stage%20V-P.jpg?width=760", text:"Улс тунхагласны баярыг тохиолдуулан Улсын драмын эрдмийн театрын уран бүтээлчид «Тэнгэрийн хүү» түүхэн туульсын жүжгийг үзэгчдийн хүсэлтээр дахин тоглохоор боллоо. Тоглолт арваннэгдүгээр сарын 26, 27, 28, 29-ний өдрүүдэд болно.\n\nТөрийн соёрхолт, Урлагийн гавьяат зүтгэлтэн Н.Наранбаатарын найруулга, Б.Цогнэмэхийн зохиол «Тэнгэрийн хүү» жүжгийг өнгөрсөн есдүгээр сард Санкт-Петербург хотноо болсон «Александринскийн олон улсын театрын фестиваль»-д толилуулсан байна. Европын авангард найруулагчид, Азийн уламжлалт театрын мастерууд Санкт-Петербургт хөл тавьж, өөрсдийн нэрийн хуудас болсон бүтээлүүдээ толилуулсаны дотор «Тэнгэрийн хүү» жүжиг багтсан нь Монголын театрын урлагийн түүхэнд тодоор бичигдэх чухал үйл явдал болсон билээ.\n\nЖүжиг нь Монголын түүх, соёл, уламжлалыг тайзны урлагаар дамжуулан үзэгчдэд хүргэх зорилготой бөгөөд найруулагч, жүжигчид, хөгжмийн зохиолчдын хамтын бүтээл юм. Үзэгчдийн хүсэлтээр дахин тоглогдож байгаа нь уг бүтээлийг олон нийт хэрхэн хүлээн авсныг харуулж байна.\n\nУлсын драмын эрдмийн театр нь Монголын тайзны урлагийн төв байгууллага бөгөөд түүхэн, сонгодог жүжгүүдийг тогтмол тайзнаа тавьдаг. «Тэнгэрийн хүү» жүжгийн тоглолтын тасалбарыг театрын кассаар болон цахимаар авах боломжтой байна.", textEn:"To mark the anniversary of the proclamation of the state, the artists of the State Academic Drama Theatre will restage the historical epic play «Son of Heaven» by popular demand. Performances will be held on November 26, 27, 28 and 29.\n\nThe play, directed by State Prize laureate and Honoured Artist N. Naranbaatar and written by B. Tsognemekh, was presented in September at the Alexandrinsky International Theatre Festival in St Petersburg. European avant-garde directors and masters of traditional Asian theatre gathered in St Petersburg to present their signature works, and the inclusion of «Son of Heaven» was an important event in the history of Mongolian theatre.\n\nThe play brings Mongolian history, culture and tradition to audiences through stage art, and is the joint work of the director, actors and composers. Its return by popular demand shows how warmly the public received the production.\n\nThe State Academic Drama Theatre is the central institution of Mongolian stage art and regularly stages historical and classical plays. Tickets for «Son of Heaven» are available at the theatre box office and online."},
  {id:19, cat:"soyol", title:"БАЯНХОНГОР: Хуучны сор бүтээлүүдээ дахин тайзнаа толилуулна", titleEn:"BAYANKHONGOR: Classic masterpieces return to the stage", time:"3 цаг", timeEn:"3 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Members%20of%20the%20Mongolian%20Military%20Song%20and%20Dance%20Academic%20Ensemble%20perform%20a%20traditional%20dance%20during%20a%20Mongolian%20culture%20event%20as%20part%20of%20exercise%20Khaan%20Quest%202013%20at%20the%20Five%20Hills%20Training%20Area%20in%20Mongolia%20130804-M-DR618-030.jpg?width=760", text:"Баянхонгор аймгийн Хөгжимт драмын театр арваннэгдүгээр сарыг «Монгол бахархал – Бүтээлч сар» болгон зарлаж, үндэсний урлагийн өв сан, уран бүтээлчдийнхээ сор бүтээлийг сэргээн тайзнаа толилуулж эхэлжээ. Энэ тухай МОНЦАМЭ арваннэгдүгээр сарын 18-нд мэдээллээ.\n\nЭнэ сарын онцлох бүтээлээр Монгол Улсын Урлагийн гавьяат зүтгэлтэн, хөгжмийн зохиолч Бадарчийн Батжаргалын хөгжим, төв халхын нэрт бүжиг дэглээч, Соёлын тэргүүний ажилтан Балжирын Дэлэгдоржийн дэглэсэн «Сүргийн дэргэд» бүжиг, хөгжмийн зохиолч, Соёлын тэргүүний ажилтан Барамсайн Шаравдоржийн хөгжим, Монгол Улсын гавьяат жүжигчин Цэндийн Алтанцэцэгийн дэглэсэн «Урианхай» бүжгийг сэргээн найруулж, үзэгчдэд хүргэхээр бэлтгэж байна.\n\nТус бүтээлүүдийг сэргээн тайзнаа тавих нь үндэсний урлагийн өвийг хадгалан хамгаалах, үе үеийн уран бүтээлчдийн туурвилыг хойч үедээ өвлүүлэх, Монголын түүх, соёл, уламжлалын үнэ цэнийг олон нийтэд таниулах зорилготой юм. Театр нь мэргэжлийн урлагийн байгууллага болсноос хойш хөгжимт драмын чиглэлээр хөгжиж байгаа бөгөөд ирэх онд тус театрын 50 жилийн ой тохиох юм.\n\nТеатрын нээлтийн үеэр Төрийн шагналт, Урлагийн гавьяат зүтгэлтэн Бирваа, Рэгсүрэн нарын «Эрдэнэтээлийн уянга» дуурь, «Гурван бүсийн нутаг» концертыг тоглосон түүхтэй. Аймгийн Соёлын ордон мэргэжлийн урлагийн байгууллага Хөгжимт драмын театр болсноор жинхэнэ мэргэжлийн өнгө аястай болж, хөгжимт драмын чиглэлээр хөгжих үндэс суурийг тавьсан гэж театр мэдээлж байна.", textEn:"The Music Drama Theatre of Bayankhongor aimag has declared November «Mongolian Pride — Creative Month» and begun reviving the finest works from its national art heritage and its artists' repertoire on stage, Montsame reported on November 18.\n\nThis month's featured works are the dance «Beside the Herd», with music by Honoured Artist and composer Badarchiin Batjargal and choreography by renowned Central Khalkha choreographer and Cultural Leading Worker Baljiriin Delegdorj, and the dance «Uriankhai», with music by composer and Cultural Leading Worker Baramsain Sharavdorj and choreography by Honoured Actress Tsendiin Altantsetseg.\n\nReviving these works aims to preserve the national art heritage, pass the creations of generations of artists on to the next generation, and introduce the public to the value of Mongolian history, culture and tradition. Since becoming a professional art institution, the theatre has developed in the music-drama field, and its 50th anniversary falls next year.\n\nAt the theatre's opening, the opera «Melody of Erdenet» by State Prize laureates and Honoured Artists Birvaa and Regsuren and the concert «Land of Three Regions» were performed. The theatre says that when the aimag's Cultural Palace became the professional Music Drama Theatre, it gained a truly professional character and laid the foundations for developing music drama."},
];

function aTitle(a){ return LANG === "en" ? (a.titleEn || a.title) : a.title; }
function aTime(a){ return LANG === "en" ? (a.timeEn || a.time) : a.time; }
function aText(a){ if(a.text) return LANG === "en" ? (a.textEn || a.text) : a.text; return SAMPLE_TEXT[LANG][a.id === 1 ? "long" : "short"]; }
function aRegion(a){ return a.region ? ((REGIONS[LANG] && REGIONS[LANG][a.region]) || a.region) : ""; }

// ===== Ханш · Цаг агаар (өдөр бүр шинэчлэгдэнэ; цаг агаарыг Open-Meteo-гоос шууд татна) =====
const RATES = {date:"2026-11-19", items:[
  {code:"USD", mnt:3605.46, chg:1}, {code:"EUR", mnt:3956.45, chg:-1}, {code:"JPY", mnt:22.62, chg:0},
  {code:"CNY", mnt:540.91, chg:1}, {code:"KRW", mnt:2.71, chg:1}, {code:"RUB", mnt:43.99, chg:1}, {code:"GBP", mnt:4749.29, chg:-1}
]};
let WEATHER = [
  {city:"Улаанбаатар", cityEn:"Ulaanbaatar", lat:47.9212, lon:106.9186, tz:"Asia/Ulaanbaatar", temp:-10, code:2},
  {city:"Токио", cityEn:"Tokyo", lat:35.6762, lon:139.6503, tz:"Asia/Tokyo", temp:11, code:0},
  {city:"Сөүл", cityEn:"Seoul", lat:37.5665, lon:126.978, tz:"Asia/Seoul", temp:-1, code:1},
  {city:"Бээжин", cityEn:"Beijing", lat:39.9042, lon:116.4074, tz:"Asia/Shanghai", temp:-1, code:0},
  {city:"Москва", cityEn:"Moscow", lat:55.7558, lon:37.6173, tz:"Europe/Moscow", temp:1, code:71}
];
function wIcon(code){
  if(code === 0) return "☀️";
  if(code === 1) return "🌤️";
  if(code === 2) return "⛅";
  if(code === 3) return "☁️";
  if(code === 45 || code === 48) return "🌫️";
  if(code === 51 || code === 53 || code === 55 || code === 80) return "🌦️";
  if(code === 56 || code === 57 || code === 61 || code === 63 || code === 65 || code === 66 || code === 67 || code === 81 || code === 82) return "🌧️";
  if(code === 71 || code === 73 || code === 75 || code === 77 || code === 85 || code === 86) return "❄️";
  if(code >= 95) return "⛈️";
  return "🌡️";
}
function fmtRate(v){
  if(v >= 100) return Math.round(v).toLocaleString("en-US");
  return v.toFixed(2);
}
function renderData(){
  const parts = [];
  RATES.items.forEach(r=>{
    let arrow = "";
    if(r.chg > 0) arrow = ' <span class="up">▲</span>';
    else if(r.chg < 0) arrow = ' <span class="down">▼</span>';
    parts.push(`<span class="tk"><b>${r.code}</b> ${fmtRate(r.mnt)}₮${arrow}</span>`);
  });
  WEATHER.forEach(w=>{
    const name = LANG === "en" ? w.cityEn : w.city;
    const t = w.temp > 0 ? "+" + w.temp : "" + w.temp;
    parts.push(`<span class="tk">${wIcon(w.code)} ${name} ${t}°C</span>`);
  });
  const html = parts.join('<span style="color:#666">•</span>');
  const track = document.getElementById("tickerTrack");
  if(track) track.innerHTML = html + '<span style="color:#666">•</span>' + html + '<span style="color:#666">•</span>';
  const usd = RATES.items.find(r=>r.code === "USD");
  const ue = document.getElementById("usdText");
  if(ue && usd) ue.textContent = "USD: " + fmtRate(usd.mnt) + "₮";
  const wt = document.getElementById("weatherText");
  const ub = WEATHER[0];
  if(wt && ub) wt.textContent = wIcon(ub.code) + " " + (LANG === "en" ? ub.cityEn : ub.city) + " " + (ub.temp > 0 ? "+" + ub.temp : ub.temp) + "°C";
}
function refreshWeather(){
  WEATHER.forEach((w, idx)=>{
    const url = "https://api.open-meteo.com/v1/forecast?latitude=" + w.lat + "&longitude=" + w.lon + "&current=temperature_2m%2Cweather_code&timezone=" + encodeURIComponent(w.tz);
    fetch(url).then(r=>r.json()).then(d=>{
      if(d && d.current){ WEATHER[idx].temp = Math.round(d.current.temperature_2m); WEATHER[idx].code = d.current.weather_code; renderData(); }
    }).catch(()=>{});
  });
}

